-- 菜品库 dump,2026-06-12 重整
-- 33 道家常菜(中式为主),覆盖早/午/晚/加餐
-- 与 DB dishes 表保持一致(也用作临时导入文件)
-- 提醒:本文件不会被 golang-migrate 自动执行(命名不带 NNNN_ 版本号);
--       需手动 docker exec -i mysql mysql ... < data.sql
-- 重要:docker 容器里的 mysql 客户端默认连接字符集是 latin1,
--       会导致中文二次编码(UTF-8 字节被当 latin1 字符再编一次)。
--       下面 SET NAMES 强制连接用 utf8mb4,跟表字符集一致。

SET NAMES utf8mb4;

