INSERT INTO `dishes_menu`.`dishes` (`id`, `name`, `slots`, `note`, `ingredients`, `estimated_time`, `image`, `created_at`, `updated_at`) VALUES
('10a2b3c4', '中式汉堡', '["breakfast","snack"]', '汉堡胚对半分开，平底锅小火煎至表面微焦；午餐肉切片煎至两面金黄，依次铺生菜、煎蛋、午餐肉，挤少许沙拉酱合起即可。', '["汉堡胚","午餐肉","鸡蛋","生菜","沙拉酱"]', 12, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('11b4d5e6', '培根手抓饼', '["breakfast","snack"]', '冷冻手抓饼无需解冻，平底锅少油小火摊平；放入培根煎香，翻面后打入鸡蛋摊匀，铺上生菜、刷甜面酱，对折卷起切段食用。', '["手抓饼","培根","鸡蛋","生菜","甜面酱"]', 10, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('12c6f7a8', '香煎紫薯块', '["breakfast","snack","dinner"]', '紫薯去皮切方块，蒸锅上汽蒸15分钟至八分熟；取出后平底锅放少许黄油，小火慢煎至四面微焦，口感香甜软糯。', '["紫薯","黄油"]', 22, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('13d8a9b0', '蜜汁蒸南瓜', '["breakfast","snack","dinner"]', '南瓜去皮去籽切厚块，整齐摆入盘中；表面淋一层蜂蜜，水开后上锅大火蒸20分钟，出锅可撒少许枸杞点缀。', '["南瓜","蜂蜜","枸杞"]', 25, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('14e0c1d2', '奶香燕麦碗', '["breakfast","snack"]', '即食燕麦倒入碗中，冲入热纯牛奶搅拌均匀，静置3分钟泡软；搭配切好的香蕉片、草莓、坚果，口感丰富营养饱腹。', '["即食燕麦","纯牛奶","香蕉","草莓","坚果"]', 6, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('15f2e3f4', '鲜肉葱花饼', '["breakfast","snack"]', '面粉加温水揉成光滑面团醒发20分钟；分成小面剂擀成薄饼，抹油、铺肉馅、撒葱花，卷起盘起再擀平，平底锅两面煎至金黄熟透。', '["面粉","猪肉馅","葱","食用油","食盐"]', 30, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('16a4f5g6', '红枣桂圆糯米粥', '["breakfast","dinner"]', '糯米提前浸泡30分钟，放入锅中加足量清水大火烧开；转小火慢熬25分钟，加入红枣、桂圆、冰糖继续熬10分钟至粥体浓稠。', '["糯米","红枣","桂圆","冰糖"]', 45, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('17b6h7i8', '银耳百合羹', '["snack","dinner"]', '银耳提前泡发撕成小朵，冷水下锅大火煮开；转小火炖煮35分钟至出胶，加入百合、莲子、冰糖，再煮10分钟关火焖5分钟即可。', '["银耳","百合","莲子","冰糖"]', 50, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('18c8j9k0', '番茄鸡蛋炒饭', '["breakfast","lunch","dinner"]', '鸡蛋打散热油滑炒定型盛出；番茄切小块炒出汤汁，倒入隔夜米饭大火翻炒散开，加鸡蛋、少许食盐、生抽炒匀出锅。', '["米饭","鸡蛋","番茄","生抽","食盐"]', 12, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('19d0l1m2', '青瓜虾仁炒饭', '["lunch","dinner"]', '虾仁去虾线用料酒、盐腌制5分钟；黄瓜切丁，先炒虾仁至变色盛出，再炒黄瓜丁，放入米饭翻炒，最后混合食材调味炒匀。', '["米饭","虾仁","黄瓜","料酒","食盐"]', 15, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('20e2n3o4', '清蒸鲈鱼', '["lunch","dinner"]', '鲈鱼处理干净，鱼身划斜刀，抹少许盐和料酒，鱼腹、鱼身铺上姜丝葱段；水开上锅大火蒸9分钟，倒掉盘中腥水，换新葱丝，淋蒸鱼豉油，浇热油激香。', '["鲈鱼","葱","姜","料酒","蒸鱼豉油","食用油","食盐"]', 22, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('21f4p5q6', '西红柿炖牛腩', '["lunch","dinner"]', '牛腩切大块冷水下锅，加姜片、料酒焯水去血沫捞出；番茄去皮切块炒出浓汁，放入牛腩翻炒，加热水、八角小火慢炖60分钟，最后加盐、少许白糖提鲜。', '["牛腩","番茄","姜","料酒","八角","食盐","白糖"]', 80, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('22a6r7s8', '清炖玉米排骨', '["lunch","dinner"]', '排骨冷水焯水去浮沫洗净，放入砂锅加姜片、足量清水大火烧开；转小火炖35分钟，加入切段玉米，继续炖20分钟，出锅前加食盐调味。', '["排骨","甜玉米","姜","食盐"]', 65, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('23b8t9u0', '红烧排骨', '["lunch","dinner"]', '排骨焯水沥干，锅中少许油放冰糖炒出枣红色糖色；倒入排骨翻炒上色，加葱姜、生抽、老抽、料酒，加热水没过食材，小火焖40分钟，大火收浓汤汁。', '["排骨","冰糖","葱","姜","生抽","老抽","料酒","食盐"]', 55, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('25d2x3y4', '蒜蓉西兰花', '["lunch","dinner"]', '西兰花切小朵，清水洗净，开水加少许盐焯水1分钟，捞出过凉水保持脆嫩；蒜末爆香，放入西兰花大火快速翻炒，加盐调味即可。', '["西兰花","大蒜","食盐"]', 11, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('26e4z5a6', '清炒上海青', '["lunch","dinner"]', '上海青摘洗干净沥干水分；热油下蒜末爆香，放入青菜大火快炒，全程不超过3分钟，菜叶变软后加少许食盐调味出锅。', '["上海青","大蒜","食盐"]', 9, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('27f6b7c8', '清炒土豆丝', '["lunch","dinner"]', '土豆切丝放入清水中浸泡洗去多余淀粉；蒜片爆香，倒入土豆丝大火翻炒，加少许生抽、食盐调味，翻炒断生即可，口感清爽。', '["土豆","大蒜","生抽","食盐"]', 13, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('28a8d9e0', '西葫芦炒肉片', '["lunch","dinner"]', '猪肉切片用生抽腌制5分钟，西葫芦切片；热油炒肉片至变色盛出，再炒西葫芦至微微变软，混合肉片，加盐、蒜末翻炒均匀。', '["西葫芦","猪肉","大蒜","生抽","食盐"]', 16, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('29b0f1g2', '木耳炒肉片', '["lunch","dinner"]', '干木耳提前泡发焯水，猪肉切片腌制；热油滑炒肉片至熟透，加入木耳一同翻炒，放少许生抽、食盐调味，翻炒入味即可。', '["干木耳","猪肉","生抽","食盐"]', 18, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('30c2h3i4', '香菇滑鸡', '["lunch","dinner"]', '鸡腿肉切块，加生抽、料酒、生粉、食用油抓匀腌制15分钟；香菇泡发切块铺底，放上鸡肉、姜丝，水开上锅大火蒸22分钟，出锅撒葱花。', '["鸡腿肉","干香菇","姜","葱","生抽","料酒","生粉","食用油"]', 38, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('32e6l7m8', '鱼香肉丝', '["lunch","dinner"]', '里脊肉切丝腌制，木耳、胡萝卜切丝备用；调配鱼香汁（糖、醋、生抽、料酒、淀粉），食材依次下锅翻炒，淋入料汁大火炒匀出锅。', '["里脊肉","木耳","胡萝卜","白糖","香醋","生抽","料酒","淀粉"]', 26, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('33f8n9o0', '宫保鸡丁', '["lunch","dinner"]', '鸡腿肉切丁腌制，花生米炸熟放凉；干辣椒、花椒炝锅，下入鸡丁翻炒至熟，加入黄瓜丁、花生米，淋上调好的酸甜料汁翻炒均匀。', '["鸡腿肉","花生米","黄瓜","干辣椒","花椒","白糖","香醋","生抽"]', 32, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('34a0p1q2', '红烧肉', '["lunch","dinner"]', '五花肉切块冷水焯水捞出；冰糖炒糖色，下入肉块翻炒上色，加葱姜、料酒、老抽、生抽，加热水小火慢炖45分钟，大火收浓汤汁。', '["五花肉","冰糖","葱","姜","料酒","老抽","生抽","食盐"]', 62, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('35b2r3s4', '冬瓜虾皮汤', '["lunch","dinner"]', '冬瓜去皮切薄片，锅中烧水放入虾皮、姜片煮3分钟；下入冬瓜片煮至透明，淋入少许香油、加盐调味，清淡解腻。', '["冬瓜","虾皮","姜","香油","食盐"]', 10, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('36c4t5u6', '紫菜蛋花汤', '["lunch","dinner"]', '清水烧开，放入紫菜、虾皮煮2分钟；鸡蛋打散缓缓淋入锅中形成蛋花，加食盐、香油、少许葱花即可出锅。', '["紫菜","虾皮","鸡蛋","葱","香油","食盐"]', 9, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('37d6v7w8', '萝卜炖肉', '["lunch","dinner"]', '白萝卜切滚刀块，五花肉切片炒出油；加生抽、姜片翻炒，倒入热水，放入萝卜块，小火炖30分钟，食材软烂后加盐调味。', '["白萝卜","五花肉","姜","生抽","食盐"]', 42, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('38e8x9y0', '凉拌黄瓜', '["lunch","dinner","snack"]', '黄瓜拍碎切段，加入蒜末、香醋、生抽、少许白糖、香油，充分拌匀，静置2分钟入味即可，爽口解腻。', '["黄瓜","大蒜","香醋","生抽","白糖","香油"]', 7, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('39f0z1a2', '卤香凤爪', '["snack","dinner"]', '鸡爪剪去指甲焯水洗净；锅中放鸡爪、八角、桂皮、生抽、老抽、冰糖、清水，大火烧开转小火卤35分钟，关火浸泡味道更佳。', '["鸡爪","八角","桂皮","生抽","老抽","冰糖"]', 45, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('41a3b4d5', '手撕包菜', '["lunch","dinner"]', '包菜用手撕成大片洗净沥干，干辣椒、蒜末炝锅，放入包菜大火快速翻炒，加生抽、食盐调味，炒至菜叶微微变软即可出锅。', '["包菜","大蒜","干辣椒","生抽","食盐"]', 12, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('42b5e6f7', '辣椒炒茄子', '["lunch","dinner"]', '茄子切条用少许盐腌制片刻杀出水分，挤干备用；青红椒切段、蒜末爆香，先炒茄子至变软，再放入辣椒一同翻炒，加生抽、食盐调味入味。', '["茄子","青辣椒","红辣椒","大蒜","生抽","食盐"]', 18, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('43c7g8h9', '清炒时蔬', '["lunch","dinner"]', '选用当季新鲜绿叶菜洗净沥干，热油下蒜末爆香，放入蔬菜大火快炒，根据口感把控时长，出锅前加少许食盐调味即可。', '["时令青菜","大蒜","食盐"]', 8, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('44d9i0j1', '蒸红薯', '["breakfast","snack","dinner"]', '红薯洗净无需去皮，整根或切块摆入盘中，水开后上锅大火蒸20分钟，用筷子能轻松扎透即熟透，香甜软糯直接食用。', '["红薯"]', 23, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00'),
('45e1k2l3', '蒸南瓜', '["breakfast","snack","dinner"]', '南瓜去皮去籽切成均匀厚块，平铺在盘中，水开后上锅大火蒸20分钟，质地绵软，原味清甜，可直接食用。', '["南瓜"]', 23, '', '2026-06-12 10:00:00', '2026-06-12 10:00:00');
